from functools import wraps

def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        print("start", func.__name__)
        out = func(*args, **kwargs)
        print("end", func.__name__)
        return out
    return wrapper

@timer
def add(a, b):
    return a + b

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

print(add(1, 2), list(fib(6)))

class Student:
    school = "SNNU"                  # 类属性
    def __init__(self, name, score):
        self.name = name              # 实例属性
        self._score = score

    @property
    def score(self):
        return self._score

    @score.setter
    def score(self, v):
        if not 0 <= v <= 100:
            raise ValueError("score 0-100")
        self._score = v

    @classmethod
    def from_string(cls, text):
        name, score = text.split(",")
        return cls(name, int(score))

    @staticmethod
    def is_pass(score):
        return score >= 60

s = Student.from_string("BW,88")
print(s.name, s.score, Student.is_pass(s.score))

